{
  "headline": "CPU Request Decrease Blocked, Memory Request Decrease OK",
  "cpu": {
    "decision": "decrease_blocked",
    "explanation": "The CPU request is blocked from decreasing because the container is throttled in 60% of periods. This indicates that the container is hitting its CPU limit, so observed usage understates demand."
  },
  "memory": {
    "decision": "decrease_ok",
    "explanation": "The memory request can decrease to 32Mi from the current 64Mi. The candidate request was initially 4Mi, but it was adjusted to meet the minimum floor of 32Mi."
  },
  "caveats": [
    "Workload name is inferred from the pod name.",
    "Revisions are not tracked, so samples from different releases are mixed.",
    "Usage figures are the highest value across pods (conservative).",
    "p50/p95/max use a 5-minute CPU rate; peak_1m uses a 1-minute rate and is still limited by the scrape interval.",
    "No latency, error-rate or SLO data is included.",
    "History covers about 4.7 h of the requested 6.0 h window."
  ]
}
